#!/usr/bin/env python3
"""Audit contract dimensions, transparency, source coverage, fonts, PCM and licences."""
from pathlib import Path
import json,struct,ctypes as C,ctypes.util,wave,math,array
R=Path(__file__).resolve().parent;O=R.parent/'game/assets'
manifest=json.loads((R/'manifest.json').read_text());assert len(manifest)==41
lib=C.CDLL(ctypes.util.find_library('cairo'))
def fn(n,args,ret):
 f=getattr(lib,n);f.argtypes=args;f.restype=ret;return f
load=fn('cairo_image_surface_create_from_png',[C.c_char_p],C.c_void_p);data=fn('cairo_image_surface_get_data',[C.c_void_p],C.POINTER(C.c_ubyte));stride=fn('cairo_image_surface_get_stride',[C.c_void_p],C.c_int);destroy=fn('cairo_surface_destroy',[C.c_void_p],None)
checks=[]
for a in manifest:
 p=O/a['file'];raw=p.read_bytes();w,h=struct.unpack('>II',raw[16:24]);assert (w,h)==(a['w'],a['h']);assert (R/'src'/(p.stem+'.svg')).exists()
 if p.stem in ['wave','wave_gold']:
  assert (w,h)==((300,104) if p.stem=='wave' else (300,116))
  # main.gd uses (150,31) crest pivot; never center these tall sprites on the hitbox.
  draw_code=(R.parent/'game/scripts/main.gd').read_text()
  assert 'center-Vector2(150,31*stretch)' in draw_code
 s=load(str(p).encode());b=C.string_at(data(s),stride(s)*h);alpha=b[3::4];assert (min(alpha)==255 if p.stem=='icon' else min(alpha)==0);destroy(s)
 checks.append({'file':a['file'],'size':f'{w}x{h}','alpha_min':min(alpha),'alpha_max':max(alpha)})
for p in sorted((O/'audio').glob('*.wav')):
 with wave.open(str(p),'rb') as f:
  assert (f.getframerate(),f.getnchannels(),f.getsampwidth())==(44100,1,2)
  a=array.array('h');a.frombytes(f.readframes(f.getnframes()));assert a[0]==a[-1]==0;assert max(map(abs,a))/32768<=10**(-1/20)
checks.append({'fonts':[(p.name,p.stat().st_size) for p in sorted((O/'fonts').iterdir()) if p.suffix in ['.ttf','.txt']]})
# Licence ledger enumerates every exported asset, not just categories.
lines=['# Meltemi asset licences','','All artwork and procedural audio below are original, self-authored for Meltemi. No third-party art or recordings were used. Original artwork/audio are provided under CC0-1.0 (https://creativecommons.org/publicdomain/zero/1.0/).','','## Original vector artwork','']
for a in manifest:lines.append(f'- `{a["file"]}` — self-authored SVG: `art/src/{Path(a["file"]).stem}.svg`; generated by `art/build_assets.py`.')
lines+=['','## Procedural audio','']
for p in sorted((O/'audio').glob('*.wav')):lines.append(f'- `audio/{p.name}` — original procedural synthesis, deterministic source `art/build_audio.py`; no recordings or samples.')
lines+=['','## Fonts','','- `fonts/Fredoka-Variable.ttf` — Fredoka by the Fredoka project authors, SIL Open Font License 1.1; official source https://github.com/google/fonts/tree/main/ofl/fredoka ; downloaded from https://raw.githubusercontent.com/google/fonts/main/ofl/fredoka/Fredoka%5Bwdth,wght%5D.ttf .','- `fonts/Fredoka-SemiBold.ttf` — static instance of the same official Fredoka variable font at weight 600, width 100, generated with fontTools; SIL OFL 1.1.','- `fonts/OFL.txt` — upstream SIL OFL 1.1 licence text: https://raw.githubusercontent.com/google/fonts/main/ofl/fredoka/OFL.txt .','','This ledger (`LICENSES.md`) documents every exported asset. Godot-generated `.import` sidecars are engine metadata, not source artwork.']
(O/'LICENSES.md').write_text('\n'.join(lines)+'\n');(R/'qa/asset_audit.json').write_text(json.dumps(checks,indent=2));print('PASS: 41 exact-size PNGs, SVG source coverage, transparent sprite/UI backgrounds, opaque icon, 12 mono 44.1kHz 16-bit WAVs, silent endpoints and <= -1dBFS peaks. Font files verified present. Licence ledger generated.')
